function earflapSVG(b){
  const e = EF[b];
  const flake = ([x,y]) => [0,60,120,180,240,300].map(a=>`<ellipse cx="${x}" cy="${y-16}" rx="6" ry="15" fill="white" transform="rotate(${a} ${x} ${y})"/>`).join('') + `<circle cx="${x}" cy="${y}" r="5" fill="#7E49C5"/>`;
  const pom = ([x,y,r]) => { let s=''; for(let i=0;i<8;i++){const a=i*Math.PI/4; s+=`<circle cx="${(x+Math.cos(a)*r*0.62).toFixed(0)}" cy="${(y+Math.sin(a)*r*0.62).toFixed(0)}" r="${(r*0.45).toFixed(0)}" fill="#FFF0CD"/>`;} return s+`<circle cx="${x}" cy="${y}" r="${(r*0.7).toFixed(0)}" fill="#FFF0CD"/>`; };
  return `<path d="${e.cap}" fill="#7E49C5"/><path d="${e.flaps}" fill="#60349E"/><path d="${e.b1}" stroke-width="14" stroke="#D9B5F4"/><path d="${e.b2}" stroke-width="15" stroke="#D9B5F4"/>` + e.flakes.map(flake).join('') + e.poms.map(pom).join('');
}
['strawberry','blueberry','raspberry','blackberry','goldenberry'].forEach(b=>{ H[b+'.hat_earflap'] = earflapSVG(b); });

